fn minimum_rooms(intervals: &[(i32, i32)]) -> usize {
    let mut count = 0;
    let mut intervals = intervals.to_vec();

    while intervals.len() > 0 {
        let (start, end) = intervals.remove(0).unwrap();
        if start <= end {
            count += 1;
        } else {
            let start = start.saturating_add(1);
            let end = end.saturating_sub(1);
            let (start2, end2) = intervals.iter().find(|&(_, x)| *x == start).unwrap();
            let room_count = minimum_rooms(&[(start2, end2.unwrap())]);
            count += room_count;
