def fibonacci_cache(n):
    """
    Computes the n-th Fibonacci number using a cache.
    The cache is a dictionary that stores the previous two numbers and their sum.
    """
    if n in (0, 1):
        return 0
    elif n in (1, 2):
        return 1
    else:
        # Cache the previous two numbers and their sum
        cache_key = (n, n - 1, n - 2)
        if n in cache:
            return cache[n]
        else:
            # Compute the sum and store it in the cache
            return cache[n] = fibonacci_cache(n - 1) + fibonacci_cache(n - 2)
def fibonacci(n):
    """
    Computes the n-th Fibonacci number using an efficient cache.
    """
    if n in (0, 1):
        return 0
    elif n in (1, 2):
        return 1
    else:
        # Cache the previous two numbers and their sum
        cache_key = (n, n - 1, n - 2)
        if n in cache:
            return cache[n]
        else:
            # Compute the sum and store it in the cache
            return cache[n] = fibonacci_cache(n - 1) + fibonacci_cache(n - 2)
