def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def prime_factors(n):
    factors = []
    while n > 1:
        if is_prime(n):
            factors.append(n)
            n = 1
        else:
            n = n // 2
    return factors
