            x = random.randint(1, 48) * self.size
            y = random.randint(1, 48) * self.size
            position = (x, y, x + self.size, y + self.size)
            if not self.isOccupied(position):
                return position

    def isOccupied(self, position):
        for segment in self.NAME_1.body:
            if self.overlap(segment, position):
                return True
        return False

    def overlap(self, rect1, rect2):
        overlap = (
            rect1[0] < rect2[2]
            and rect1[2] > rect2[0]
            and rect1[1] < rect2[3]
            and rect1[3] > rect2[1]
        )
        return overlap

    def newFood(self):
        self.position = self.randomPosition()
        self.draw()
