    cout << "Shortest path from 0 to 1: " << path << endl;

    // Run NAME_1's algorithm to find the shortest path from node 1 to node 2
    vector<int> path2 = NAME_1(graph);
    cout << "Shortest path from 1 to 2: " << path2 << endl;

    // Run NAME_1's algorithm to find the shortest path from node 2 to node 3
    vector<int> path3 = NAME_1(graph);
    cout << "Shortest path from 2 to 3: " << path3 << endl;

