void morphCircleToRectangle(Offset start, double radius, double x, double y, double width, double height) {
  Paint paint = Paint()
    ..color = Colors.black
    ..strokeCap = StrokeCap.round
    ..strokeWidth = 2.0;
  Canvas canvas = Canvas(width: width + 100, height: height + 100);
  for (double angle = 0; angle <= 2 * Math.PI; angle += Math.PI / 10) {
    double x1 = start.dx + radius * cos(angle);
    double y1 = start.dy + radius * sin(angle);
    double x2 = start.dx + width + radius * cos(angle);
    double y2 = start.dy + height + radius * sin(angle);
    canvas.drawLine(Offset(x1, y1), Offset(x2, y2), paint: paint);
  }
}
