def dfs(graph, start):
    visited = set()
    for node in graph:
        if node not in visited:
            dfs(graph, node, visited)

def dfs(graph, node, visited):
    visited.add(node)
    if node == start:
        return
    for neighbor in graph[node]:
        dfs(graph, neighbor, visited)
