def display_labyrinth(canvas, labyrinth, wall_color, floor_color, start_color, end_color):
    # Define the dimensions of each cell in the labyrinth
    cell_width = canvas.winfo_width() / len(labyrinth[0])
    cell_height = canvas.winfo_height() / len(labyrinth)

    # Draw each cell in the labyrinth
    for row in range(len(labyrinth)):
        for col in range(len(labyrinth[0])):
            # Calculate the coordinates of the top-left corner of the cell
            x0, y0 = col * cell_width, row * cell_height
            x1, y1 = x0 + cell_width, y0 + cell_height

            # Draw the floor of the cell
            if not labyrinth[row][col]:
                canvas.create_rectangle(x0, y0, x1, y1, fill=floor_color, outline="")

            # Draw the walls of the cell
            if labyrinth[row][col]:
                if row == 0:
                    canvas.create_line(x0, y0, x1, y0, fill=wall_color, width=2)
                if col == 0:
                    canvas.create_line(x0, y0, x0, y1, fill=wall_color, width=2)
                if row == len(labyrinth) - 1:
                    canvas.create_line(x0, y1, x1, y1, fill=wall_color, width=2)
                if col == len(labyrinth[0]) - 1:
                    canvas.create_line(x1, y0, x1, y1, fill=wall_color, width=2)

            # Draw the start and end points of the labyrinth
            if row == 0 and not labyrinth[row][col]:
                canvas.create_rectangle(x0, y0, x1, y1, fill=start_color, outline="")
