```python
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def prime_decomposition(n):
    if is_prime(n):
        return [n]
    else:
        primes = [2]
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                n = n // i
                if n != 1:
                    primes.append(i)
        return primes

# Example usage
num = 121
print("Prime decomposition of", num, ":", prime_decomposition(num))
```
