import random

def random_number(max_num):
    return random.randint(1, max_num)

def arithmetic_operation(operations):
    return random.choice(operations)

def generate_question(max_num, operations):
    num1 = random_number(max_num)
    num2 = random_number(max_num)
    operation = arithmetic_operation(operations)

    if operation == '+':
        answer = num1 + num2
    elif operation == '-':
        answer = num1 - num2
    elif operation == '*':
        answer = num1 * num2
    elif operation == '/':
        answer = num1 / num2
    else:
        return None

    return f"{num1} {operation} {num2}", answer

def main():
    max_num = 20
    operations = ['+', '-', '*', '/']

    while True:
        question, answer = generate_question(max_num, operations)
        if question:
            print(question)
            user_answer = int(input("Your answer: "))
            if user_answer == answer:
                print("Correct!")
            else:
                print("Wrong. The correct answer is:", answer)
        else:
            print("Invalid question generated. Please try again.")

if __name__ == "__main__":
    main()
