int main(int argc, char *argv[]) {
    // Open a FITS file for writing
    Fits *fptr;
    if (!cfitsio_fits_open(&fptr, argv[1], READWRITE, &errmsg)) {
        fprintf(stderr, "Error opening FITS file: %s\n", errmsg);
        return 1;
    }

    // Create a new HDU
    Hdu *new_hdu = cfitsio_create_hdu(0, 0, 0, &errmsg);
    if (!new_hdu) {
        fprintf(stderr, "Error creating HDU: %s\n", errmsg);
        return 1;
    }

    // Set the data and header for the new HDU
    double *data = (double*)malloc(10*10*sizeof(double));
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            data[i*10+j] = i+j;
        }
    }
    new_hdu->data = data;
    new_hdu->header = CFITS_HDU_HAVE_IMAGE;

    // Write the new HDU to the FITS file
    cfitsio_write_hdu(fptr, new_hdu, &errmsg);

    // Close the FITS file
    cfitsio_fits_close(fptr, &errmsg);
    free(data);
    return 0;
}
