def flatten_dict(dict_):
    flat = {}
    for key, value in dict_.items():
        if isinstance(value, dict):
            for nested_key, nested_value in value.items():
                flat[key + '/' + nested_key] = nested_value
        else:
            flat[key] = value
    return flat
```

